<?php view('layouts/header',['seo'=>$seo]); ?><section class="bk-section bk-reviews-page"><div class="container"><div class="bk-section-head center"><span class="section-eyebrow">CUSTOMER REVIEWS</span><h1>What customers say about Big Kahuna</h1><p>Read recent feedback from our connected review platforms.</p></div><?php $overall=$summary['overall']??['rating'=>0,'count'=>0]; ?><div class="bk-review-summary"><div class="bk-review-score"><strong><?= $overall['rating']>0?e(number_format((float)$overall['rating'],1)):'—' ?></strong><span>out of 5</span></div><div class="bk-review-summary-copy"><div class="bk-review-stars"><?php for($i=1;$i<=5;$i++):?><i class="fa-solid fa-star <?= $i<=round((float)$overall['rating'])?'is-on':''?>"></i><?php endfor;?></div><strong><?= (int)$overall['count']?> reviews</strong><span>From Google and Tripadvisor</span></div><div class="bk-review-source-pills"><?php foreach(['google'=>'Google','tripadvisor'=>'Tripadvisor'] as $k=>$label):if(!empty($summary[$k])):?><span><strong><?=e($label)?></strong> <?=number_format((float)$summary[$k]['rating'],1)?> ★ · <?= (int)$summary[$k]['count']?></span><?php endif;endforeach;?></div></div><?php if(empty($reviews)):?><div class="card" style="margin-top:24px;text-align:center"><h2>Reviews are being connected</h2><p>Check back soon for recent customer feedback.</p></div><?php endif;?><div class="bk-testimonial-grid bk-external-review-grid" style="margin-top:28px"><?php foreach($reviews as $r):?><article class="bk-testimonial-card bk-external-review-card"><div class="bk-testimonial-stars"><?php for($i=0;$i<(int)$r['rating'];$i++):?><i class="fa-solid fa-star"></i><?php endfor;?></div><?php if($r['title']!==''):?><h3><?=e($r['title'])?></h3><?php endif;?><p class="bk-testimonial-quote">&ldquo;<?=e($r['comment'])?>&rdquo;</p><div class="bk-external-review-meta"><strong><?=e($r['reviewer_name'])?></strong><span><?=e(ucfirst($r['source']))?> · <?=e(date('d M Y',strtotime($r['review_date'])))?></span></div><?php if(!empty($r['review_url'])):?><a class="bk-review-source-link" href="<?=e($r['review_url'])?>" target="_blank" rel="noopener">View on <?=e(ucfirst($r['source']))?> <i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif;?></article><?php endforeach;?></div><div class="bk-review-actions"><?php if(!empty($links['google'])):?><a class="btn btn-outline" href="<?=e($links['google'])?>" target="_blank" rel="noopener"><i class="fa-brands fa-google"></i> Leave a Google review</a><?php endif;?><?php if(!empty($links['tripadvisor'])):?><a class="btn btn-outline" href="<?=e($links['tripadvisor'])?>" target="_blank" rel="noopener"><i class="fa-solid fa-plane"></i> Leave a Tripadvisor review</a><?php endif;?></div></div></section><?php view('layouts/footer'); ?>